def even_numbers(limit):
    n = 0
    while n <= limit:
        yield n            # pauses here, resumes on next call
        n += 2

for value in even_numbers(6):
    print(value)            # 0 2 4 6

squares = (x * x for x in range(5))   # generator expression, lazy
print(next(squares), next(squares))    # 0 1
